  /// Friendly message for any thrown error. Server `message` is used for
  /// validation / conflict style errors where it carries useful detail.
  String errorText(Object error) {
    if (error is ApiException) {
      switch (error.code) {
        case ApiErrorCodes.networkUnavailable:
          return errorNetwork;
        case ApiErrorCodes.timeout:
          return errorTimeout;
        case ApiErrorCodes.unauthorized:
          return error.message.isNotEmpty && error.status == 401
              ? error.message
              : errorUnauthorized;
        case ApiErrorCodes.forbidden:
          return errorForbidden;
        case ApiErrorCodes.notFound:
          return errorNotFound;
        case ApiErrorCodes.rateLimited:
          return errorRateLimited;
        case ApiErrorCodes.aiNotConfigured:
          return errorAiNotConfigured;
        case ApiErrorCodes.cancelled:
          return errorGeneric;
        default:
          return error.message.isNotEmpty ? error.message : errorGeneric;
      }
    }
    return errorGeneric;
  }

